#!/bin/sh
# Prints the Homebrew formula for a release: scripts/formula.sh v0.1.0 checksums.txt
set -eu
v=$1
sum() { grep " reel-$v-$1.tar.gz\$" "$2" | cut -d' ' -f1; }
url="https://github.com/nessalabs/nessa-video/releases/download/$v/reel-$v"
cat <<RB
# Generated by scripts/formula.sh in nessalabs/nessa-video; edits here are replaced.
class Reel < Formula
  desc "Turn short .reel scripts into explainer videos"
  homepage "https://github.com/nessalabs/nessa-video"
  version "${v#v}"
  license "GPL-2.0-or-later"

  on_macos do
    on_arm do
      url "$url-darwin-arm64.tar.gz"
      sha256 "$(sum darwin-arm64 "$2")"
    end
    on_intel do
      url "$url-darwin-amd64.tar.gz"
      sha256 "$(sum darwin-amd64 "$2")"
    end
  end

  on_linux do
    on_arm do
      url "$url-linux-arm64.tar.gz"
      sha256 "$(sum linux-arm64 "$2")"
    end
    on_intel do
      url "$url-linux-amd64.tar.gz"
      sha256 "$(sum linux-amd64 "$2")"
    end
  end

  def install
    bin.install "reel"
    doc.install "README.md", "THIRD_PARTY_NOTICES.md"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/reel version")
  end
end
RB
